import { useState } from "react";
import { API } from "../api/api";

export default function CreatePoll() {
  const [question, setQuestion] = useState("");
  const [type, setType] = useState("student");
  const [options, setOptions] = useState(["", ""]);

  const addOption = () => {
    setOptions([...options, ""]);
  };

  const updateOption = (value, index) => {
    const updated = [...options];
    updated[index] = value;
    setOptions(updated);
  };

  const create = async () => {
    try {
      const formattedOptions = options
        .filter((o) => o.trim() !== "")
        .map((o) => ({ text: o, votes: 0 }));

      await API.post("/polls", {
        question,
        type,
        options: formattedOptions,
      });

      alert("Poll Created 🚀");

      setQuestion("");
      setType("student");
      setOptions(["", ""]);
    } catch (err) {
      console.error(err);
      alert("Error creating poll");
    }
  };

  return (
    <>
      <style>{`
        *{
          margin:0;
          padding:0;
          box-sizing:border-box;
          font-family:Arial, sans-serif;
        }

        .page{
          min-height:100vh;
          display:flex;
          justify-content:center;
          align-items:center;
          padding:30px;
          background:radial-gradient(circle at top,#1e3a8a,#0b1220 60%);
          color:white;
        }

        /* MAIN CARD */
        .card{
          width:500px;
          padding:25px;
          border-radius:18px;

          background:#111827;
          border:1px solid rgba(255,255,255,0.08);

          box-shadow:0 15px 40px rgba(0,0,0,0.5);
        }

        /* TITLE */
        .title{
          text-align:center;
          font-size:26px;
          font-weight:700;
          margin-bottom:20px;
        }

        /* SECTION LABEL */
        .label{
          font-size:13px;
          color:#9ca3af;
          margin:12px 0 6px;
        }

        input, select{
          width:100%;
          padding:12px;
          border-radius:10px;
          border:none;
          outline:none;
          background:#1f2937;
          color:white;
          font-size:14px;
        }

        input::placeholder{
          color:#6b7280;
        }

        select option{
          color:black;
        }

        /* OPTION ROW */
        .option-row{
          margin:8px 0;
        }

        /* BUTTONS */
        .btn{
          width:100%;
          padding:12px;
          margin-top:12px;
          border:none;
          border-radius:10px;
          font-size:14px;
          cursor:pointer;
          transition:0.3s;
        }

        .add{
          background:#22c55e;
          color:white;
        }

        .add:hover{
          background:#16a34a;
        }

        .create{
          background:#3b82f6;
          color:white;
        }

        .create:hover{
          background:#2563eb;
          transform:scale(1.02);
        }

        /* SMALL HOVER LIFT */
        .card:hover{
          transform:translateY(-5px);
          transition:0.3s;
        }
      `}</style>

      <div className="page">

        <div className="card">

          <div className="title">Create Poll 📊</div>

          {/* QUESTION */}
          <div className="label">Question</div>
          <input
            placeholder="Enter your poll question..."
            value={question}
            onChange={(e) => setQuestion(e.target.value)}
          />

          {/* TYPE */}
          <div className="label">Category</div>
          <select value={type} onChange={(e) => setType(e.target.value)}>
            <option value="student">Student</option>
            <option value="teacher">Teacher</option>
            <option value="general">General</option>
          </select>

          {/* OPTIONS */}
          <div className="label">Options</div>

          {options.map((opt, i) => (
            <div className="option-row" key={i}>
              <input
                placeholder={`Option ${i + 1}`}
                value={opt}
                onChange={(e) => updateOption(e.target.value, i)}
              />
            </div>
          ))}

          {/* ADD OPTION */}
          <button className="btn add" onClick={addOption}>
            + Add Option
          </button>

          {/* CREATE */}
          <button className="btn create" onClick={create}>
            Create Poll 🚀
          </button>

        </div>

      </div>
    </>
  );
}
